package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DailyOwnerLimitExceededException;

/**
 * Rejects creating an owner once {@value #DAILY_LIMIT} or more owners have already been
 * registered on the same business day (counted by {@link org.springframework.samples.petclinic.model.Owner#getRegistrationDate()}).
 * The count uses the new owner's adjusted registration date — the supplied or defaulted date
 * rolled forward off a weekend (see {@link RegistrationDates}), matching the date {@link BuildOwner}
 * will stamp. A day at capacity is rejected 429 via {@link DailyOwnerLimitExceededException}.
 */
public class CheckOwnerDailyLimit {

    static final int DAILY_LIMIT = 100;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DailyOwnerLimitExceededException {
        LocalDate businessDay = RegistrationDates.effective(request.getRegistrationDate());
        long registeredThatDay = RegistrationDates.countRegisteredOn(businessDay, ownerRepository);
        if (registeredThatDay >= DAILY_LIMIT) {
            throw new DailyOwnerLimitExceededException(
                    DAILY_LIMIT + " or more owners have already been created on " + businessDay);
        }
    }
}
=== DetectOwnerDuplicate ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerIdentityException;

/**
 * Rejects a create that duplicates an existing owner's identity. The single identity key is the
 * SHA-256 of {@code normalizedTelephone | lowerEmail | soundex(lastName)}
 * (see {@link Owner#getIdentityKey()}); a new owner whose key equals that of any already-persisted,
 * non-deleted owner is rejected 409 via {@link DuplicateOwnerIdentityException}.
 *
 * <p>Soft-deleted owners are ignored, matching the rest of the create endpoint's duplicate and
 * identity checks. The email-domain blocklist runs earlier in the pipeline
 * (see {@link ValidateOwnerEmailDomain}), so a blocklisted email is already rejected 400 before this
 * step is reached. Because the telephone is part of the key, two owners with the same last name and
 * postcode but different telephones are not duplicates here — they fall through to the soft match in
 * {@link DetectOwnerPossibleDuplicate}.
 *
 * <p>Runs after {@link BuildOwner} (so the built owner carries its normalized telephone, lower-cased
 * email and last name) and before {@link SaveOwner}; the new owner has no id yet, so it never matches
 * itself.
 */
public class DetectOwnerDuplicate {

    public void service(@Val Owner owner, OwnerRepository ownerRepository)
            throws DuplicateOwnerIdentityException {
        String identityKey = owner.getIdentityKey();
        for (Owner existing : ownerRepository.findAll()) {
            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
                continue; // an owner never duplicates itself
            }
            if (existing.isDeleted()) {
                continue; // soft-deleted owners are ignored
            }
            if (identityKey.equals(existing.getIdentityKey())) {
                throw new DuplicateOwnerIdentityException(
                        "An owner with the same identity already exists");
            }
        }
    }
}
=== CheckOwnerCityCapacity ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.CityOwnerLimitExceededException;

/**
 * Rejects creating an owner when the owner's city already holds {@value #CITY_CAPACITY} or more
 * owners. A city at capacity is rejected 409 via {@link CityOwnerLimitExceededException}.
 */
public class CheckOwnerCityCapacity {

    static final int CITY_CAPACITY = 50;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws CityOwnerLimitExceededException {
        String city = request.getCity();
        if (countInCity(ownerRepository, city) >= CITY_CAPACITY) {
            throw new CityOwnerLimitExceededException(
                    "City " + city + " already has " + CITY_CAPACITY + " or more owners");
        }
    }

    /**
     * Existing owners whose city equals {@code city} case-insensitively, backing the 409 gate. Also
     * used by {@link DeriveOwnerCapacityWarning} so the capacity warning provably counts the same
     * population this gate rejects on. A {@code null} city counts as no matches.
     */
    static long countInCity(OwnerRepository ownerRepository, String city) {
        return ownerRepository.findAll().stream()
                .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
                .count();
    }
}

